def extract_date(text):
    # Common date patterns, including some OCR errors
    # Try to find something that looks like DD/MM/YYYY or YYYY-MM-DD
    # Handle misread separators like . or spaces
    patterns = [
        r'(\d{1,2})[./\s](\d{1,2})[./\s](\d{4})',  # DD/MM/YYYY or MM/DD/YYYY
        r'(\d{4})[./\s](\d{1,2})[./\s](\d{1,2})',  # YYYY/MM/DD
        r'(\d{1,2})[./\s](\d{1,2})[./\s](\d{2})',  # DD/MM/YY
        r'(\d{8})', # DDMMYYYY
    ]

    for pattern in patterns:
        matches = re.findall(pattern, text)
        for match in matches:
            if isinstance(match, tuple):
                d, m, y = match
                if len(y) == 2:
                    y = '20' + y # Assume 20xx
            else:
                # Handle DDMMYYYY
                d, m, y = match[:2], match[2:4], match[4:]

            # Try various combinations of d and m
            for day, month in [(d, m), (m, d)]:
                try:
                    # Basic cleaning of day/month (OCR might misread 0 as 6 or 8)
                    # But let's try direct conversion first
                    dt = datetime(int(y), int(month), int(day))
                    if 2010 <= dt.year <= 2030:
                        return dt.strftime('%Y-%m-%d')
                except ValueError:
                    # Try fixing common OCR errors if month is invalid
                    try:
                        fixed_month = month.replace('6', '0').replace('8', '0').replace('b', '0').replace('o', '0').replace('O', '0')
                        fixed_day = day.replace('o', '0').replace('O', '0')
                        dt = datetime(int(y), int(fixed_month), int(fixed_day))
                        if 2010 <= dt.year <= 2030 and int(fixed_month) <= 12:
