        r'(\d{4}[-/]\d{2}[-/]\d{2})',
        r'(\d{2}[-/]\d{2}[-/]\d{2})',
    ]
    for pattern in patterns:
        matches = re.findall(pattern, text)
        for match in matches:
            for fmt in ('%d/%m/%Y', '%m/%d/%Y', '%d-%m-%Y', '%m-%d-%Y', '%Y/%m/%d', '%Y-%m-%d', '%d/%m/%y', '%d-%m-%y'):
                try:
                    dt = datetime.strptime(match.replace('-', '/'), fmt.replace('-', '/'))
                    if 2010 <= dt.year <= 2030:
                        return dt.strftime('%Y-%m-%d')
                except ValueError:
                    continue
    return None

def extract_total_amount(text):
    lines = [line.strip() for line in text.split('\n') if line.strip()]
    keywords = ['GRAND TOTAL', 'TOTAL RM', 'TOTAL: RM', 'TOTAL AMOUNT', 'TOTAL', 'AMOUNT', 'TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL']
    exclusion = ['SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE', 'CASH TENDERED']

    for kw in keywords:
        for i, line in enumerate(lines):
            if kw in line.upper():
                if any(ex in line.upper() for ex in exclusion):
                    continue
                # Try finding amount in current line
                m = re.findall(r'(\d{1,3}(?:,\d{3})*\.\d{2})', line)
                if m: return m[-1].replace(',', '')
                # Try next line
                if i + 1 < len(lines):
                    m = re.findall(r'(\d{1,3}(?:,\d{3})*\.\d{2})', lines[i+1])
                    if m: return m[-1].replace(',', '')
    return None

