import os
import re
import pytesseract
from PIL import Image
import openpyxl
from datetime import datetime

def extract_date(text):
    patterns = [
        r'\b(\d{2}[-/]\d{2}[-/]\d{4})\b',
        r'\b(\d{4}[-/]\d{2}[-/]\d{2})\b',
        r'\b(\d{2}[-/]\d{2}[-/]\d{2})\b',
    ]
    for pattern in patterns:
        matches = re.findall(pattern, text)
        for match in matches:
            for fmt in ('%d/%m/%Y', '%m/%d/%Y', '%d-%m-%Y', '%m-%d-%Y', '%Y/%m/%d', '%Y-%m-%d', '%d/%m/%y', '%d-%m-%y'):
                try:
                    dt = datetime.strptime(match.replace('-', '/'), fmt.replace('-', '/'))
                    if 2010 <= dt.year <= 2030:
                        return dt.strftime('%Y-%m-%d')
                except ValueError:
                    continue
    return None

def extract_total_amount(text):
    lines = [line.strip() for line in text.split('\n') if line.strip()]
    keywords = ['GRAND TOTAL', 'TOTAL RM', 'TOTAL: RM', 'TOTAL AMOUNT', 'TOTAL', 'AMOUNT', 'TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL']
    exclusion = ['SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE', 'CASH TENDERED']

    for kw in keywords:
        for i, line in enumerate(lines):
            if kw in line.upper():
                if any(ex in line.upper() for ex in exclusion):
                    continue
                # Try finding amount in current line
                line_clean = line.replace('u', '0').replace('o', '0').replace('O', '0')
                m = re.findall(r'(\d{1,3}(?:,\d{3})*\.\d{2,3})', line_clean)
                if m:
                    val = m[-1].replace(',', '')
                    if len(val.split('.')[-1]) == 3 and val.endswith('0'):
                        val = val[:-1]
                    return val
                # Try next line
                if i + 1 < len(lines):
                    next_line_clean = lines[i+1].replace('u', '0').replace('o', '0').replace('O', '0')
                    m = re.findall(r'(\d{1,3}(?:,\d{3})*\.\d{2,3})', next_line_clean)
                    if m:
                        val = m[-1].replace(',', '')
                        if len(val.split('.')[-1]) == 3 and val.endswith('0'):
                            val = val[:-1]
                        return val
    return None

def main():
    img_dir = '/app/workspace/dataset/img'
    output_file = '/app/workspace/stat_ocr.xlsx'
    files = sorted([f for f in os.listdir(img_dir) if f.endswith('.jpg')])
    results = []
    for filename in files:
        img_path = os.path.join(img_dir, filename)
        img = Image.open(img_path)

        date, total = None, None
        for scale in [1, 2]:
            v = img if scale == 1 else img.resize((img.width*scale, img.height*scale), Image.Resampling.LANCZOS)
            text = pytesseract.image_to_string(v)
            if not date: date = extract_date(text)
            if not total: total = extract_total_amount(text)
            if date and total: break

        results.append({'filename': filename, 'date': date, 'total_amount': total})

    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(['filename', 'date', 'total_amount'])
    for res in results:
        ta = res['total_amount']
        if ta:
            try:
                ta = "{:.2f}".format(float(ta))
            except:
                pass
        ws.append([res['filename'], res['date'], ta])
    wb.save(output_file)

if __name__ == "__main__":
    main()
